mapper.update:
update research_proposal
title=#{title},background=#{background},objectives=#{objectives}, project_scope=#{projectScope},out_of_scope=#{outOfScope}, research_content=#{researchContent},methodology=#{methodology},innovation_points=#{innovationPoints}, success_criteria=#{successCriteria},planned_start_date=#{plannedStartDate},planned_end_date=#{plannedEndDate}, requested_budget=#{requestedBudget}, update_by=#{username},version=version+1
where proposal_id=#{proposalId} and version=#{version}
